SECTORS = ["Mining", "Renewable Energy", "Wind Energy", "Infrastructure", "Power & Utilities", "Agriculture", "Energy"]

UNSUPPORTED_KEYWORDS = [
    "attrition", "employee", "hr", "turnover", "hiring", "salary", "payroll",
    "ebitda", "p&l", "profit and loss", "net profit", "tax", "balance sheet",
    "cac", "customer acquisition cost", "marketing spend", "ad spend",
    "nps", "csat", "customer satisfaction", "feedback score",
    "drone fleet", "telemetry", "battery", "gps trace", "flight duration", "pilot salary",
    "weather", "joke", "president", "capital", "news", "stock", "python", "program", "code"
]

GREETING_KEYWORDS = [
    "hi", "hello", "hey", "greetings", "good morning", "good afternoon", "good evening", "howdy",
    "who are you", "what can you do", "what do you do", "how can you help", "how can you help me", "help", "capabilities"
]

EXPLICIT_OVERVIEW_KEYWORDS = [
    "general summary", "overall summary", "business performance", "company overview",
    "how are we doing", "show me performance", "overall performance", "business overview", "summary", "overview"
]

def normalize_sector(val):
    if not val: return None
    s = str(val).strip().lower()
    if 'mine' in s or 'mining' in s: return 'Mining'
    if 'renew' in s or 'solar' in s or 'green' in s: return 'Renewable Energy'
    if 'wind' in s: return 'Wind Energy'
    if 'infra' in s or 'road' in s or 'urban' in s: return 'Infrastructure'
    if 'power' in s or 'util' in s or 'grid' in s: return 'Power & Utilities'
    if 'agri' in s or 'farm' in s or 'crop' in s: return 'Agriculture'
    if 'energy' in s: return 'Energy'
    return str(val).strip()

def parse_query_intent(query):
    q_lower = query.strip().lower()
    for kw in UNSUPPORTED_KEYWORDS:
        if kw in q_lower:
            return {"metric": "unsupported_metric", "sector_filter": None, "needs_clarification": False, "clarification_question": None}

    words = re.findall(r'\w+', q_lower)
    if words and words[0] in ["hi", "hello", "hey", "greetings", "howdy"] and len(words) <= 3:
        return {"metric": "greeting", "sector_filter": None, "needs_clarification": False, "clarification_question": None}
    if q_lower in GREETING_KEYWORDS or any(k in q_lower for k in ["what do you do", "what can you do", "how can you help"]):
        return {"metric": "greeting", "sector_filter": None, "needs_clarification": False, "clarification_question": None}

    metric = None
    if any(k in q_lower for k in ["pipeline", "deals", "funnel", "opportunity", "opportunities", "stage"]):
        metric = "pipeline"
    elif any(k in q_lower for k in ["revenue", "sales", "billed", "amount", "collection", "collected", "money", "income"]):
        metric = "revenue"
    elif any(k in q_lower for k in ["delayed", "delay", "bottleneck", "pending", "overdue", "hold"]):
        metric = "delayed_work_orders"
    elif any(k in q_lower for k in ["customer", "customers", "client", "clients", "account", "accounts"]):
        metric = "top_customers"
    elif any(k in q_lower for k in ["sector", "sectors", "industry", "industries", "service"]):
        metric = "sector_performance"
    elif any(k in q_lower for k in ["work order", "work orders", "wo", "execution", "tracker"]):
        metric = "work_orders"
    elif any(k in q_lower for k in EXPLICIT_OVERVIEW_KEYWORDS):
        metric = "general_overview"

    if not metric:
        return {"metric": "unsupported_metric", "sector_filter": None, "needs_clarification": False, "clarification_question": None}

    sector_filter = None
    if any(k in q_lower for k in ["energy", "renewable", "renewables", "solar"]):
        sector_filter = "Renewable Energy"
    else:
        for sec in SECTORS:
            if sec.lower() in q_lower:
                sector_filter = sec
                break

    if sector_filter:
        sector_filter = normalize_sector(sector_filter)

    needs_clarification = False
    clarification_q = None
    if query.strip().lower() in ["revenue", "show me revenue", "what is revenue", "pipeline", "show me pipeline"]:
        needs_clarification = True
        clarification_q = "Would you like to see total revenue, revenue broken down by sector, or top customers?" if "revenue" in q_lower else "Would you like total pipeline value, pipeline by deal stage, or pipeline by owner?"

    return {
        "metric": metric,
        "sector_filter": sector_filter,
        "needs_clarification": needs_clarification,
        "clarification_question": clarification_q
    }

def calculate_total_revenue(work_orders, sector_filter=None):
    filtered = work_orders
    if sector_filter:
        filtered = [wo for wo in work_orders if normalize_sector(wo.get('sector')) == sector_filter]

    tot_excl = sum(float(wo.get('base_amount') or 0) for wo in filtered)
    tot_incl = sum(float(wo.get('total_amount_gst') or 0) for wo in filtered)
    tot_billed = sum(float(wo.get('billed_amount') or 0) for wo in filtered)
    tot_collected = sum(float(wo.get('collected_amount') or 0) for wo in filtered)
    missing = sum(1 for wo in filtered if wo.get('base_amount') is None)

    return {
        "count": len(filtered),
        "total_revenue_excl_gst": round(tot_excl, 2),
        "total_revenue_incl_gst": round(tot_incl, 2),
        "total_billed_excl_gst": round(tot_billed, 2),
        "total_collected_incl_gst": round(tot_collected, 2),
        "total_receivable": round(max(0, tot_billed - tot_collected), 2),
        "missing_amount_count": missing
    }

def calculate_pipeline(deals, sector_filter=None):
    filtered = deals
    if sector_filter:
        filtered = [d for d in deals if normalize_sector(d.get('sector')) == sector_filter]

    open_deals = [d for d in filtered if d.get('stage_category') == 'Open']
    won_deals = [d for d in filtered if d.get('stage_category') == 'Won']

    tot_val = sum(float(d.get('value') or 0) for d in open_deals)
    w_val = sum(float(d.get('value') or 0) * float(d.get('probability') or 0) for d in open_deals)

    by_stage_dict = {}
    for d in open_deals:
        st = d.get('stage') or 'Unspecified'
        val = float(d.get('value') or 0)
        if st not in by_stage_dict:
            by_stage_dict[st] = {"stage": st, "count": 0, "value": 0.0}
        by_stage_dict[st]["count"] += 1
        by_stage_dict[st]["value"] += val

    by_stage = sorted(list(by_stage_dict.values()), key=lambda x: x["value"], reverse=True)
    missing = sum(1 for d in filtered if d.get('value') is None)

    return {
        "total_deals_count": len(filtered),
        "open_deals_count": len(open_deals),
        "won_deals_count": len(won_deals),
        "total_pipeline_value": round(tot_val, 2),
        "weighted_pipeline_value": round(w_val, 2),
        "deals_by_stage": by_stage,
        "missing_value_count": missing
    }

def calculate_delayed_work_orders(work_orders):
    delayed = [wo for wo in work_orders if wo.get('is_delayed') or wo.get('status') in ['Delayed', 'Pending Update']]
    total = len(work_orders)
    pct = round((len(delayed) / total * 100), 1) if total > 0 else 0.0
    
    samples = []
    for wo in delayed[:5]:
        samples.append({
            "id": wo.get('id'),
            "deal_name": wo.get('name'),
            "customer": wo.get('customer'),
            "status": wo.get('status'),
            "amount": float(wo.get('base_amount') or 0),
            "sector": wo.get('sector'),
            "owner": wo.get('owner')
        })

    return {
        "delayed_count": len(delayed),
        "total_work_orders": total,
        "delayed_percentage": pct,
        "sample_delayed": samples
    }

def process_query_standalone(query):
    trace = [f"Received User Query: '{query}'"]
    intent = parse_query_intent(query)
    trace.append(f"Parsed Intent: metric='{intent['metric']}', sector_filter='{intent['sector_filter']}'")

    if intent['needs_clarification'] and intent['clarification_question']:
        return {
            "query": query,
            "direct_answer": intent['clarification_question'],
            "intent": intent,
            "key_numbers": {},
            "insights": ["Please refine your query or choose an option above for more specific insights."],
            "data_notes": [],
            "execution_trace": trace
        }

    mode_label = "Local Seed Dataset Fallback"
    trace.append(f"Retrieved Data: {len(DEALS)} Deals, {len(WORK_ORDERS)} Work Orders (Data Mode: {mode_label})")

    key_numbers = {}
    insights = []
    direct_answer = ""
    supporting_data = []
    data_notes = [
        "Note: 181 out of 346 deals in the assignment dataset have missing/unstated deal values.",
        "Note: 1 out of 176 work orders have unstated base revenue amounts."
    ]

    metric = intent['metric']
    sector_filter = intent['sector_filter']

    if metric == "revenue":
        rev = calculate_total_revenue(WORK_ORDERS, sector_filter=sector_filter)
        key_numbers = rev
        sec_str = f" in the {sector_filter} sector" if sector_filter else ""
        direct_answer = f"Total recorded revenue (excl. GST) from work orders{sec_str} is ₹{rev['total_revenue_excl_gst']:,.2f} across {rev['count']} work orders."
        insights.append(f"Total billed value: ₹{rev['total_billed_excl_gst']:,.2f}.")
        insights.append(f"Total collected amount: ₹{rev['total_collected_incl_gst']:,.2f}.")
    elif metric == "pipeline":
        pipe = calculate_pipeline(DEALS, sector_filter=sector_filter)
        key_numbers = pipe
        sec_str = f" for the {sector_filter} sector" if sector_filter else ""
        direct_answer = f"Current active sales pipeline{sec_str} stands at ₹{pipe['total_pipeline_value']:,.2f} across {pipe['open_deals_count']} open deals (Weighted Pipeline: ₹{pipe['weighted_pipeline_value']:,.2f})."
        for st in pipe['deals_by_stage'][:3]:
            insights.append(f"Stage '{st['stage']}': {st['count']} deals totaling ₹{st['value']:,.2f}")
        supporting_data = pipe['deals_by_stage']
    elif metric == "delayed_work_orders":
        delays = calculate_delayed_work_orders(WORK_ORDERS)
        key_numbers = delays
        direct_answer = f"Currently, {delays['delayed_count']} out of {delays['total_work_orders']} work orders ({delays['delayed_percentage']}%) are delayed or requiring updates."
        for item in delays['sample_delayed'][:4]:
            insights.append(f"WO '{item['deal_name']}' ({item['customer']}) in {item['sector']} sector - Status: {item['status']}")
        supporting_data = delays['sample_delayed']
    elif metric == "greeting":
        direct_answer = "Hello! I'm Skylark Drones' Business Intelligence Agent. Ask me any natural-language question about Skylark Drones' sales pipeline, revenue, delayed work orders, or sectoral performance."
        key_numbers = {"status": "greeting"}
    elif metric == "unsupported_metric":
        direct_answer = "I can only answer questions based on Skylark Drones' available Monday.com business data, including revenue, sales pipeline, work orders, customers, and sector performance. I don't have data to answer that question."
        key_numbers = {"status": "unsupported_metric"}
        data_notes.append("Requested metric is outside the available Monday.com Deals and Work Orders datasets.")
    else: # general_overview
        rev = calculate_total_revenue(WORK_ORDERS)
        pipe = calculate_pipeline(DEALS)
        delays = calculate_delayed_work_orders(WORK_ORDERS)
        key_numbers = {
            "total_revenue_excl_gst": rev['total_revenue_excl_gst'],
            "total_pipeline_value": pipe['total_pipeline_value'],
            "weighted_pipeline_value": pipe['weighted_pipeline_value'],
            "open_deals_count": pipe['open_deals_count'],
            "open_deals": pipe['open_deals_count'],
            "delayed_count": delays['delayed_count'],
            "delayed_work_orders": delays['delayed_count']
        }
        direct_answer = f"Business Performance Summary: Total Work Order Revenue is ₹{rev['total_revenue_excl_gst']:,.2f}, Active Sales Pipeline is ₹{pipe['total_pipeline_value']:,.2f} across {pipe['open_deals_count']} open deals, and {delays['delayed_count']} work orders are currently delayed or flagged for updates."
        insights.append(f"Total Billed (excl GST): ₹{rev['total_billed_excl_gst']:,.2f}")
        insights.append(f"Total Collected (incl GST): ₹{rev['total_collected_incl_gst']:,.2f}")
        insights.append(f"Weighted Sales Pipeline: ₹{pipe['weighted_pipeline_value']:,.2f}")

    trace.append("Completed deterministic calculations & response formatting.")

    return {
        "query": query,
        "direct_answer": direct_answer,
        "intent": intent,
        "key_numbers": key_numbers,
        "insights": insights,
        "data_notes": data_notes,
        "supporting_data": supporting_data,
        "execution_trace": trace
    }

class handler(BaseHTTPRequestHandler):
    def do_GET(self):
        try:
            path = self.path
            if 'favicon' in path or 'ico' in path:
                self.send_response(204)
                self.end_headers()
                return
            elif 'health' in path:
                res = {
                    "status": "online",
                    "app": "Skylark Drones Monday.com BI Agent",
                    "version": "1.0.0",
                    "environment": "production",
                    "monday_integration": {
                        "mode": "local_seed_fallback",
                        "is_configured": False
                    }
                }
                body = json.dumps(res, ensure_ascii=False).encode('utf-8')
                self.send_response(200)
                self.send_header('Content-Type', 'application/json; charset=utf-8')
                self.send_header('Access-Control-Allow-Origin', '*')
                self.end_headers()
                self.wfile.write(body)
            else:
                self.send_response(200)
                self.send_header('Content-Type', 'text/html; charset=utf-8')
                self.send_header('Access-Control-Allow-Origin', '*')
                self.end_headers()
                self.wfile.write(SINGLE_FILE_HTML.encode('utf-8'))
        except Exception:
            self.send_response(200)
            self.send_header('Content-Type', 'text/html; charset=utf-8')
            self.end_headers()
            self.wfile.write(SINGLE_FILE_HTML.encode('utf-8'))

    def do_POST(self):
        try:
            content_length = int(self.headers.get('Content-Length', 0))
            post_data = self.rfile.read(content_length) if content_length > 0 else b'{}'
            req_data = json.loads(post_data.decode('utf-8'))
        except Exception:
            req_data = {}
            
        raw_q = req_data.get('query', '')
        
        try:
            res = process_query_standalone(raw_q)
        except Exception as err:
            res = {
                "query": raw_q,
                "direct_answer": f"Error executing query: {str(err)}",
                "intent": {"metric": "error", "dimensions": []},
                "key_numbers": {},
                "insights": [],
                "data_notes": [f"Execution error: {str(err)}"],
                "execution_trace": [f"Error: {str(err)}"]
            }
            
        body = json.dumps(res, ensure_ascii=False).encode('utf-8')
        self.send_response(200)
        self.send_header('Content-Type', 'application/json; charset=utf-8')
        self.send_header('Access-Control-Allow-Origin', '*')
        self.send_header('Access-Control-Allow-Methods', 'GET, POST, OPTIONS')
        self.send_header('Access-Control-Allow-Headers', 'Content-Type')
        self.end_headers()
        self.wfile.write(body)

    def do_OPTIONS(self):
        self.send_response(200)
        self.send_header('Access-Control-Allow-Origin', '*')
        self.send_header('Access-Control-Allow-Methods', 'GET, POST, OPTIONS')
        self.send_header('Access-Control-Allow-Headers', 'Content-Type')
        self.end_headers()

app = handler
